const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const boston = ee.Geometry.Point([-71.0589, 42.3601]);
  const startDate = '2019-01-29';
  const endDate = '2019-02-05';

  // 2. Data Acquisition - ERA5 for 2m temperature
  const era5 = ee.ImageCollection('ECMWF/ERA5/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(boston)
    .select('mean_2m_air_temperature_max');

  const collectionSize = era5.size().getInfo();
  console.log(`Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Extract daily maximum temperatures
  const tempData = era5.map(function(image) {
    const date = image.date().format('YYYY-MM-dd');
    const maxTemp = image.reduceRegion({
      reducer: ee.Reducer.max(),
      geometry: boston,
      scale: 10000,
      maxPixels: 1e9
    }).get('mean_2m_air_temperature_max');

    return ee.Feature(null, {
      'date': date,
      'max_temp': maxTemp
    });
  });

  const tempList = tempData.aggregate_array('max_temp').getInfo();
  const dateList = tempData.aggregate_array('date').getInfo();

  console.log("Daily max temperatures (K):");
  for (let i = 0; i < dateList.length; i++) {
    console.log(`${dateList[i]}: ${tempList[i]?.toFixed(2) || 'No data'}`);
  }

  // 4. Check for valid data and calculate range
  const validTemps = tempList.filter(temp => temp !== null && temp !== undefined);

  if (validTemps.length === 0) {
    console.log("No valid temperature data");
    console.log("<answer>C2</answer>");
    return;
  }

  const maxTempK = Math.max(...validTemps);
  const minTempK = Math.min(...validTemps);
  const rangeK = maxTempK - minTempK;
  const rangeC = rangeK - 273.15; // Convert from Kelvin to Celsius

  console.log(`Max daily temp: ${(maxTempK - 273.15).toFixed(1)}°C`);
  console.log(`Min daily temp: ${(minTempK - 273.15).toFixed(1)}°C`);
  console.log(`Temperature range: ${rangeC.toFixed(1)}°C`);

  // 5. Validation & Final Answer
  if (isNaN(rangeC) || rangeC < -100 || rangeC > 100) {
    console.log("<answer>C3</answer>");
  } else if (rangeC >= 30) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
